<html lang="fr" class="dark">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Futuristic Oasis - Scroll Experience</title>

    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;600;800&display=swap" rel="stylesheet">

    <style>
        body {
            font-family: 'Plus Jakarta Sans', sans-serif;
            scroll-behavior: smooth;
        }

        /* --- BARRE DE NAVIGATION EXTENSIBLE --- */
        header {
            transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
            border-bottom: 1px solid transparent;
        }

        /* État rétracté au scroll */
        .nav-shrunk {
            padding-top: 0.75rem !important;
            padding-bottom: 0.75rem !important;
            background: rgba(255, 255, 255, 0.8) !important;
            backdrop-filter: blur(15px) saturate(150%);
            border-bottom: 1px solid rgba(0, 0, 0, 0.05);
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.04);
        }

        .dark .nav-shrunk {
            background: rgba(15, 23, 42, 0.8) !important;
            border-bottom: 1px solid rgba(255, 255, 255, 0.05);
        }

        /* Effet Focus sur les liens */
        .nav-link {
            position: relative;
            padding: 0.5rem 1.25rem;
            transition: all 0.3s ease;
        }
        .nav-link::after {
            content: '';
            position: absolute;
            bottom: 0; left: 50%;
            width: 0; height: 2px;
            background: #3b82f6;
            transition: all 0.3s ease;
            transform: translateX(-50%);
        }
        .nav-link:hover::after {
            width: 20px;
        }

        /* Bulles sociales animées */
        .social-bubble {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            background: rgba(59, 130, 246, 0.1);
            color: #3b82f6;
            transition: all 0.3s;
            transform: scale(0);
            opacity: 0;
        }
        .nav-shrunk .social-bubble {
            transform: scale(1);
            opacity: 1;
        }

        /* Animation des cartes au scroll */
        .scroll-reveal {
            opacity: 0;
            transform: translateY(30px);
            transition: all 0.8s ease-out;
        }
        .scroll-reveal.visible {
            opacity: 1;
            transform: translateY(0);
        }
    </style>
</head>
<body class="bg-white dark:bg-slate-950 text-slate-900 dark:text-slate-100">

    <header id="navbar" class="fixed top-0 w-full py-8 z-50">
