                </div>
            </div>
        </div>
    </section>

    <section id="features" class="py-32 bg-slate-50 dark:bg-slate-900/50">
        <div class="container mx-auto px-6">
            <div class="text-center max-w-3xl mx-auto mb-20 scroll-reveal">
